def on_recv_rsp(self, rsp_pb):
        """receive response callback function"""
        if rsp_pb.ret != xrpc.NO_ERROR:
            return
        if rsp_pb.cmd_id != self.cmd_id:
            return
        if rsp_pb.seq_id != self.seq_id:
            return
        if rsp_pb.body.type != xrpc.RESPONSE_BODY:
            return
        if rsp_pb.body.response.ret != xrpc.NO_ERROR:
            return
        self.rsp_cb(rsp_pb.body.response.data)

